enum Item { Pen, Pad, Ink }

struct Record {
    item: Item,
    unit_price: Int,
    quantity: Int,
}

fn cost(record: &Record) -> Int {
    record.unit_price * record.quantity
}

fn name(record: &Record) -> Str {
    match record.item {
        Item::Pen => "pen",
        Item::Pad => "pad",
        Item::Ink => "ink",
    }
}

fn main() {
    let pen = Record {
        item: Item::Pen,
        unit_price: 3,
        quantity: 4,
    };
    let pad = Record {
        item: Item::Pad,
        unit_price: 9,
        quantity: 2,
    };
    let ink = Record {
        item: Item::Ink,
        unit_price: 5,
        quantity: 3,
    };
    let total_cost = cost(&pen) + cost(&pad) + cost(&ink);
    print(total_cost);
    let items = vec![&pen, &pad, &ink];
    let most_expensive = items.iter().max_by_key(|r| cost(r)).unwrap();
    print_str(name(most_expensive));
    drop pen;
    drop pad;
    drop ink;
}

fn main() {
    let (pen_unit_price, pen_quantity) = (3, 4);
    let (pad_unit_price, pad_quantity) = (9, 2);
    let (ink_unit_price, ink_quantity) = (5, 3);

    let pen_cost = pen_unit_price * pen_quantity;
    let pad_cost = pad_unit_price * pad_quantity;
    let ink_cost = ink_unit_price * ink_quantity;

    let total_cost = pen_cost + pad_cost + ink_cost;
    println!("Combined cost of all items: {}", total_cost);

    let (highest_cost_item, item_name) = if pen_cost > pad_cost && pen_cost > ink_cost {
        (pen_cost, "pen")
    } else if pad_cost > ink_cost {
        (pad_cost, "pad")
    } else {
        (ink_cost, "ink")
    };

    println!("Item with the highest cost: {} ({})", item_name, highest_cost_item);
}

